
CREATE TABLE mfg_machine (id UUID PRIMARY KEY, code VARCHAR(40) UNIQUE NOT NULL, name VARCHAR(160) NOT NULL, process VARCHAR(24) NOT NULL, capacity_kg NUMERIC(19,6) NOT NULL CHECK(capacity_kg>0), state VARCHAR(20) NOT NULL CHECK(state IN ('AVAILABLE','UNAVAILABLE')));
CREATE TABLE mfg_mold (id UUID PRIMARY KEY, code VARCHAR(40) UNIQUE NOT NULL, name VARCHAR(160) NOT NULL, cavities INTEGER NOT NULL CHECK(cavities>0), state VARCHAR(20) NOT NULL CHECK(state IN ('AVAILABLE','UNAVAILABLE')));
CREATE TABLE mfg_compatibility (machine_id UUID REFERENCES mfg_machine(id), mold_id UUID REFERENCES mfg_mold(id), PRIMARY KEY(machine_id,mold_id));
CREATE TABLE mfg_employee (id UUID PRIMARY KEY, code VARCHAR(40) UNIQUE NOT NULL, name VARCHAR(160) NOT NULL, user_subject VARCHAR(160) UNIQUE NOT NULL, active BOOLEAN NOT NULL);
CREATE TABLE mfg_qualification (employee_id UUID REFERENCES mfg_employee(id), machine_id UUID REFERENCES mfg_machine(id), valid_until DATE NOT NULL, PRIMARY KEY(employee_id,machine_id));
CREATE TABLE mfg_shift (id UUID PRIMARY KEY, employee_id UUID NOT NULL REFERENCES mfg_employee(id), starts_at TIMESTAMP WITH TIME ZONE NOT NULL, ends_at TIMESTAMP WITH TIME ZONE NOT NULL, CHECK(ends_at>starts_at));
CREATE TABLE mfg_recipe (id UUID PRIMARY KEY, product_id UUID NOT NULL REFERENCES catalog_product(id), revision INTEGER NOT NULL CHECK(revision>0), process VARCHAR(24) NOT NULL, yield_factor NUMERIC(12,6) NOT NULL CHECK(yield_factor>0 AND yield_factor<=1), settings TEXT NOT NULL, packaging TEXT NOT NULL, created_at TIMESTAMP WITH TIME ZONE NOT NULL, UNIQUE(product_id, revision));
CREATE TABLE mfg_component (recipe_id UUID REFERENCES mfg_recipe(id), material_id UUID REFERENCES catalog_product(id), kg_per_unit NUMERIC(19,6) NOT NULL CHECK(kg_per_unit>0), PRIMARY KEY(recipe_id,material_id));
CREATE TABLE mfg_operation (recipe_id UUID REFERENCES mfg_recipe(id), sequence_no INTEGER NOT NULL CHECK(sequence_no>0), name VARCHAR(160) NOT NULL, minutes_per_unit NUMERIC(19,6) NOT NULL CHECK(minutes_per_unit>0), PRIMARY KEY(recipe_id,sequence_no));
CREATE TABLE mfg_inspection_plan (id UUID PRIMARY KEY, product_id UUID NOT NULL REFERENCES catalog_product(id), revision INTEGER NOT NULL, metrics TEXT NOT NULL, UNIQUE(product_id,revision));
CREATE TABLE mfg_order (id UUID PRIMARY KEY, code VARCHAR(40) UNIQUE NOT NULL, sales_reference VARCHAR(120) NOT NULL, recipe_id UUID NOT NULL REFERENCES mfg_recipe(id), inspection_plan_id UUID NOT NULL REFERENCES mfg_inspection_plan(id), planned_qty NUMERIC(19,6) NOT NULL CHECK(planned_qty>0), good_qty NUMERIC(19,6) NOT NULL CHECK(good_qty>=0), reject_qty NUMERIC(19,6) NOT NULL CHECK(reject_qty>=0), state VARCHAR(20) NOT NULL CHECK(state IN ('PLANNED','SCHEDULED','RUNNING','COMPLETED')));
CREATE TABLE mfg_lot (id UUID PRIMARY KEY, code VARCHAR(40) UNIQUE NOT NULL, material_id UUID NOT NULL REFERENCES catalog_product(id), supplier_reference VARCHAR(120) NOT NULL, location VARCHAR(80) NOT NULL, received_kg NUMERIC(19,6) NOT NULL CHECK(received_kg>0), remaining_kg NUMERIC(19,6) NOT NULL CHECK(remaining_kg>=0 AND remaining_kg<=received_kg), quality VARCHAR(20) NOT NULL CHECK(quality IN ('PENDING','APPROVED','QUARANTINED','REJECTED')));
CREATE TABLE mfg_consumption (event_id UUID PRIMARY KEY, order_id UUID NOT NULL REFERENCES mfg_order(id), lot_id UUID NOT NULL REFERENCES mfg_lot(id), kg NUMERIC(19,6) NOT NULL CHECK(kg>0), created_at TIMESTAMP WITH TIME ZONE NOT NULL);
CREATE TABLE mfg_output (event_id UUID PRIMARY KEY, order_id UUID NOT NULL REFERENCES mfg_order(id), good_qty NUMERIC(19,6) NOT NULL CHECK(good_qty>=0), reject_qty NUMERIC(19,6) NOT NULL CHECK(reject_qty>=0), reason VARCHAR(240) NOT NULL, created_at TIMESTAMP WITH TIME ZONE NOT NULL);
CREATE TABLE mfg_downtime (id UUID PRIMARY KEY, order_id UUID NOT NULL REFERENCES mfg_order(id), starts_at TIMESTAMP WITH TIME ZONE NOT NULL, ends_at TIMESTAMP WITH TIME ZONE NOT NULL, reason VARCHAR(240) NOT NULL, CHECK(ends_at>starts_at));
CREATE TABLE mfg_batch (id UUID PRIMARY KEY, order_id UUID UNIQUE NOT NULL REFERENCES mfg_order(id), qty NUMERIC(19,6) NOT NULL CHECK(qty>0), quality VARCHAR(20) NOT NULL CHECK(quality IN ('PENDING','APPROVED','QUARANTINED','REJECTED')));
CREATE TABLE mfg_inspection (id UUID PRIMARY KEY, batch_id UUID NOT NULL REFERENCES mfg_batch(id), measurements TEXT NOT NULL, passed BOOLEAN NOT NULL, inspector VARCHAR(160) NOT NULL, created_at TIMESTAMP WITH TIME ZONE NOT NULL);
CREATE TABLE mfg_nonconformity (id UUID PRIMARY KEY, batch_id UUID NOT NULL REFERENCES mfg_batch(id), reason VARCHAR(500) NOT NULL, resolved BOOLEAN NOT NULL, created_at TIMESTAMP WITH TIME ZONE NOT NULL);
CREATE TABLE mfg_schedule (order_id UUID PRIMARY KEY REFERENCES mfg_order(id), machine_id UUID NOT NULL REFERENCES mfg_machine(id), mold_id UUID REFERENCES mfg_mold(id), employee_id UUID NOT NULL REFERENCES mfg_employee(id), shift_id UUID NOT NULL REFERENCES mfg_shift(id), starts_at TIMESTAMP WITH TIME ZONE NOT NULL, ends_at TIMESTAMP WITH TIME ZONE NOT NULL, CHECK(ends_at>starts_at));
CREATE TABLE mfg_maintenance_block (id UUID PRIMARY KEY, machine_id UUID NOT NULL REFERENCES mfg_machine(id), starts_at TIMESTAMP WITH TIME ZONE NOT NULL, ends_at TIMESTAMP WITH TIME ZONE NOT NULL, reason VARCHAR(240) NOT NULL, CHECK(ends_at>starts_at));
CREATE TABLE mfg_pallet (id UUID PRIMARY KEY, code VARCHAR(40) UNIQUE NOT NULL, batch_id UUID NOT NULL REFERENCES mfg_batch(id), qty NUMERIC(19,6) NOT NULL CHECK(qty>0));
CREATE TABLE mfg_dispatch_reference (id UUID PRIMARY KEY, pallet_id UUID UNIQUE NOT NULL REFERENCES mfg_pallet(id), shipment_reference VARCHAR(120) NOT NULL, customer_reference VARCHAR(120) NOT NULL);
CREATE TABLE mfg_audit (id UUID PRIMARY KEY, entity_id UUID NOT NULL, action VARCHAR(80) NOT NULL, details TEXT NOT NULL, actor VARCHAR(160) NOT NULL, created_at TIMESTAMP WITH TIME ZONE NOT NULL);
CREATE INDEX ix_mfg_schedule_machine ON mfg_schedule(machine_id,starts_at,ends_at);
CREATE INDEX ix_mfg_schedule_employee ON mfg_schedule(employee_id,starts_at,ends_at);
CREATE INDEX ix_mfg_schedule_mold ON mfg_schedule(mold_id,starts_at,ends_at);
CREATE INDEX ix_mfg_consumption_order ON mfg_consumption(order_id);
CREATE INDEX ix_mfg_consumption_lot ON mfg_consumption(lot_id);
CREATE INDEX ix_mfg_inspection_batch ON mfg_inspection(batch_id,created_at);
